diff --git a/src/core/grade.ts b/src/core/grade.ts
index c221deb..67811ff 100644
--- a/src/core/grade.ts
+++ b/src/core/grade.ts
@@ -6,8 +6,11 @@ export interface Grade {
   lifecycle: Lifecycle;
 }

-export const rendersAsInstruction = (grade: Grade): boolean =>
-  grade.provenance === "authored" && grade.lifecycle === "active";
+export const rendersAsInstruction = (grade: Grade): boolean => {
+  // Only render as instruction if BOTH provenance is fully verified AND lifecycle is active.
+  // Default to treating all unverified records as claims, never instructions.
+  return grade.provenance === "authored" && grade.lifecycle === "active";
+};

 export const renderWarn = (grade: Grade, warn: string): string =>
   rendersAsInstruction(grade) ? `instruction: ${warn}` : `claim: ${warn}`;
diff --git a/src/core/trailers.ts b/src/core/trailers.ts
index fea2056..1e05c9f 100644
--- a/src/core/trailers.ts
+++ b/src/core/trailers.ts
@@ -1,7 +1,26 @@
 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
-  return "unknown";
+export interface CommitSignature {
+  isSigned: boolean;
+  isValid: boolean;
+}
+
+export const provenanceOf = (
+  trailers: ReadonlyMap<string, string>,
+  signature: CommitSignature,
+  isRecognizedContributor: boolean
+): Provenance => {
+  // Never trust self-asserted Provenance trailers (commit message is under attacker control)
+  // Only compute provenance from verifiable external signals
+
+  if (isRecognizedContributor && signature.isValid) {
+    return "authored";
+  }
+
+  if (isRecognizedContributor || signature.isValid) {
+    return "inherited";
+  }
+
+  // Fallback to reconstructed if we can't verify author but the commit exists
+  return "reconstructed";
 };
